#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  # %q shell-escapes the value: connection strings contain & and ?, which
  # would otherwise split the line when .env.backup is sourced.
  printf '%s=%q\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: M6 backups (docs/implementation-plan.md "Backups") -- the parts
# scripts/backup.sh and scripts/backupBlobs.ts can't do themselves: creating
# infra, editing crontab, and proving a restore actually works.
#
# Run this WHILE LOGGED INTO NEXTCLOUD'S LXC (101 on `pve`: `pct enter 101`
# from the pve host). Every value it captures lands in .env.backup in the
# keli checkout inside that LXC, which is where cron will read it from --
# running this wizard anywhere else writes the file to the wrong machine.
# The Pi 5 is deliberately NOT involved: it only runs nginx + Tailscale.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
ENV_FILE=".env.backup"

banner "keli M6: backups setup (Nextcloud LXC 101)"
note "This wizard assumes you're inside LXC 101 right now, in (or about to"
note "clone into) the directory where the keli repo should live long-term."

# ── Stage 1: get the code into the LXC ─────────────────────────────────────
stage "Get the keli repo into LXC 101"
say "scripts/backup.sh and scripts/backupBlobs.ts already live in the repo"
say "(merged to main) -- cron just needs a checkout of it, plus tools."
step "Install prerequisites: apt install -y git rsync postgresql-client nodejs npm"
note "pg_dump must be >= the Neon server's major version (check with: pg_dump --version)."
step "If this is the first time: git clone git@github.com:rupakstephen/keli.git"
step "If it's already here: cd into it and run: git pull origin main"
step "Then install deps (gives you tsx + @vercel/blob): npm install --ignore-scripts"
note "--ignore-scripts skips the Prisma postinstall, which needs DATABASE_URL and isn't used by backups."
step "Confirm Node/npm work: node -v && npm -v"
confirm "Repo cloned/updated and npm install finished cleanly?" || warn "fix that before continuing, then re-run this wizard"
ask KELI_DIR "Full path to the keli checkout in this LXC (e.g. /root/keli):"
# Everything from here on (.env.backup, relative paths) is written relative
# to THIS script's own working directory -- not wherever you separately `cd`
# in your terminal -- so the wizard process itself moves into the checkout.
cd "$KELI_DIR" || { warn "couldn't cd into $KELI_DIR -- check the path and re-run"; exit 1; }
note "wizard now working from: $(pwd)"

# ── Stage 2: read-only Neon role ───────────────────────────────────────────
stage "Neon: create a read-only backup role"
say "Never reuse the app's main DATABASE_URL for backups -- a separate"
say "SELECT-only role means a compromised backup script can't write or drop"
say "anything."
open_url "https://console.neon.tech/app/projects"
step "Open the keli project (the neondb database)."
step "Go to the project's 'Roles' tab -> 'Add role' -> name it e.g. keli_backup."
step "Neon generates the password for you -- you'll reveal it from here in a moment."
note "Neon-created roles start with no table grants, so we still need to grant SELECT."
step "Open the SQL Editor, connect as your existing (owner) role, and run:"
say ""
say "  GRANT CONNECT ON DATABASE neondb TO keli_backup;"
say "  GRANT USAGE ON SCHEMA public TO keli_backup;"
say "  GRANT SELECT ON ALL TABLES IN SCHEMA public TO keli_backup;"
say "  ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO keli_backup;"
say ""
confirm "Ran those 4 GRANT statements successfully?" || warn "the role won't be able to read anything until these run -- go back and run them"
step "Back on the Roles tab, click keli_backup -> reveal its connection string"
step "(or use Neon's 'Connect' modal, database=neondb, role=keli_backup)."
ask_secret BACKUP_DATABASE_URL "Paste the keli_backup connection string:"
write_env BACKUP_DATABASE_URL "$BACKUP_DATABASE_URL"

# ── Stage 3: Blob token ────────────────────────────────────────────────────
stage "Vercel Blob: reuse the read-write token"
say "The backup script only lists + downloads blobs, so the same token the"
say "app already uses (BLOB_READ_WRITE_TOKEN) is fine -- no need for a"
say "separate one at this scale."
open_url "https://vercel.com/dashboard"
step "Open the keli project -> Storage -> your Blob store -> '.env.local' tab."
step "Copy the BLOB_READ_WRITE_TOKEN value shown there."
ask_secret BLOB_READ_WRITE_TOKEN "Paste BLOB_READ_WRITE_TOKEN:"
write_env BLOB_READ_WRITE_TOKEN "$BLOB_READ_WRITE_TOKEN"

# ── Stage 4: Nextcloud destination folder (+ optional second copy) ──────────
stage "Nextcloud: pick the backup destination folder"
say "Both the db dump and synced photos land inside Nextcloud's data directory"
say "(on the 500GB drive, bind-mounted at /mnt/nextcloud-storage), so they show"
say "up as regular versioned files."
step "Find your Nextcloud user's files folder, e.g. /mnt/nextcloud-storage/<user>/files"
step "Create a subfolder for backups, e.g.:"
say "    mkdir -p /mnt/nextcloud-storage/<user>/files/keli-backups"
ask NEXTCLOUD_BACKUP_DIR "Full path to that folder:"
write_env NEXTCLOUD_BACKUP_DIR "$NEXTCLOUD_BACKUP_DIR"
note "Files written as root need chown + a rescan to appear in the Nextcloud UI;"
note "the cron line in stage 6 does both."
say ""
say "That drive also holds Nextcloud's live data, so a dead drive loses both."
say "Optional second copy: rsync to the Mac Mini (794GB free in its thin pool)."
step "Set up passwordless SSH from this LXC to mini:"
say "    ssh-keygen -t ed25519   (if you have no key)  &&  ssh-copy-id root@192.168.1.250"
step "Create the target on mini:  ssh root@192.168.1.250 mkdir -p /root/keli-backups"
if confirm "Set up the mini rsync second copy now?"; then
  write_env OFFSITE_RSYNC_TARGET "root@192.168.1.250:/root/keli-backups/"
else
  warn "skipping the second copy -- the backup shares a drive with live Nextcloud data"
fi

# ── Stage 5: manual test run ────────────────────────────────────────────────
stage "Run the backup once by hand"
say "This proves the whole chain works before cron ever touches it."
step "From the keli checkout (inside LXC 101), run:"
say "    cd \"$KELI_DIR\""
say "    set -a; source .env.backup; set +a"
say "    ./scripts/backup.sh"
step "Check the output: it should print the .sql.gz path, then a photo count."
step "Confirm the .sql.gz file and any photos actually appear in $NEXTCLOUD_BACKUP_DIR"
step "(and in /root/keli-backups on mini, if you enabled the second copy)."
confirm "backup.sh ran clean and the files are there?" || warn "don't move on until this works -- check DATABASE_URL/token typos, or pg_dump/psql/rsync being installed (apt install postgresql-client rsync)"

# ── Stage 6: cron ───────────────────────────────────────────────────────────
stage "Install the nightly cron job"
say "Runs backup.sh every night, logging output so a silent failure is still visible."
step "Open your crontab:"
say "    crontab -e"
step "Add this line (edit the path if $KELI_DIR isn't right):"
say "    0 3 * * * cd $KELI_DIR && (set -a; . ./.env.backup; set +a; ./scripts/backup.sh) >> $KELI_DIR/backup.log 2>&1 && chown -R www-data:www-data $NEXTCLOUD_BACKUP_DIR && sudo -u www-data php /var/www/nextcloud/occ files:scan --path=\"<user>/files/keli-backups\" >> $KELI_DIR/backup.log 2>&1"
note "Adjust <user> and the occ path to your install. Use root's crontab."
step "Save and exit, then confirm it's there: crontab -l"
confirm "Cron entry added and visible in 'crontab -l'?" || warn "the nightly backup won't run until this line is actually saved"

# ── Stage 7: prove the backup restores ──────────────────────────────────────
stage "Verify: restore the dump and diff against Neon"
say "The plan's own rule: a backup that's never been restored isn't verified."
say "This needs Docker (or any local Postgres) -- easiest on your laptop; scp a dump over."
step "Start a scratch Postgres:"
say "    docker run --rm -d --name keli-restore-test -p 5433:5432 -e POSTGRES_PASSWORD=test postgres:16"
step "Find the newest dump in $NEXTCLOUD_BACKUP_DIR/db (or mini:/root/keli-backups/db), then restore it:"
say "    gunzip -c $NEXTCLOUD_BACKUP_DIR/db/keli-<timestamp>.sql.gz | psql postgresql://postgres:test@localhost:5433/postgres"
step "Compare a row count against the live Neon DB, e.g. for User:"
say "    psql \"\$BACKUP_DATABASE_URL\" -c 'select count(*) from \"User\";'"
say "    psql postgresql://postgres:test@localhost:5433/postgres -c 'select count(*) from \"User\";'"
confirm "Counts matched (or any diff is fully explained, e.g. writes made mid-test)?" || warn "don't consider M6 done until a restore has actually been verified once"
step "Clean up the scratch container:"
say "    docker rm -f keli-restore-test"

finish
note "M6 backups are now provisioned. This wizard script (setup-m6-backup.sh)"
note "is committed with the backup scripts -- delete it once you're done, or keep it around if"
note "you'll ever need to redo this setup on new hardware."
